class SearchSubtitleDownloadManager {
    subtitleDataPath = '';
    subtitleData = {};
    waitLoad = new wait_some_thing/* WaitSomeThing */.o();
    status = 0;
    constructor(){
        this.subtitleDataPath = external_path_.join((0,xxx_node_path/* GetProfilesPath */.W8)(), 'SubTitleDownload/subtitledata.json');
    }
    async getSubtitleDataById(taskId, scid) {
        await this.load();
        if (!this.subtitleData[taskId]) {
            return undefined;
        }
        let subtitleItem = this.subtitleData[taskId].find((item)=>item.scid === scid);
        return subtitleItem;
    }
    async saveSubtitleData(taskId, subtitleItem) {
        await this.load();
        if (!this.subtitleData[taskId]) {
            this.subtitleData[taskId] = [];
        }
        let i = 0;
        for(i = 0; i < this.subtitleData[taskId].length; i++){
            if (this.subtitleData[taskId][i].scid === subtitleItem.scid) {
                this.subtitleData[taskId][i] = subtitleItem;
                break;
            }
        }
        if (i === this.subtitleData[taskId].length) {
            this.subtitleData[taskId].push(subtitleItem);
        }
        const jsonStr = JSON.stringify(this.subtitleData, undefined, 2);
        await fs_utilities/* FileSystemAWNS,writeFileAW */.X.writeFileAW(this.subtitleDataPath, jsonStr);
    }
    async load() {
        if (this.status === 2) {
            return;
        }
        if (this.status === 1) {
            await this.waitLoad.waitDone();
            return;
        }
        this.status = 1;
        let exsitStatus = await fs_utilities/* FileSystemAWNS,existsAW */.X.existsAW(this.subtitleDataPath);
        if (!exsitStatus) {
            exsitStatus = await fs_utilities/* FileSystemAWNS,mkdirsAW */.X.mkdirsAW(external_path_.dirname(this.subtitleDataPath));
            if (exsitStatus) {
                await fs_utilities/* FileSystemAWNS,writeFileAW */.X.writeFileAW(this.subtitleDataPath, '{}');
            }
        } else {
            const buffer = await fs_utilities/* FileSystemAWNS,readFileAW */.X.readFileAW(this.subtitleDataPath);
            if (buffer) {
                try {
                    this.subtitleData = JSON.parse(buffer.toString());
                } catch (e) {
                    this.subtitleData = {};
                }
            }
        }
        this.status = 2;
        this.waitLoad.done();
    }
}
