class EventEmitter {
    events;
    constructor(){
        this.events = {};
    }
    on(event, listener) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push({
            isOnce: false,
            listener: listener
        });
    }
    once(event, listener) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push({
            isOnce: false,
            listener: listener
        });
    }
    off(event, listener) {
        const listeners = this.events[event];
        if (listeners) {
            this.events[event] = listeners.filter((item)=>item.listener !== listener);
        }
    }
    emit(event, ...args) {
        const arr = this.events[event];
        if (Array.isArray(arr)) {
            const listeners = Array.from(arr);
            if (listeners) {
                for (const item of listeners){
                    if (item.isOnce) {
                        this.off(event, item.listener);
                    }
                    item.listener(...args);
                }
            }
        }
    }
}

