;// CONCATENATED MODULE: ../player-comp/client/aplayer-history.ts

class AplayerPlayHistory {
    apiProxy = null;
    eventContainor = new external_events_.EventEmitter();
    listCache = [];
    async initApiProxy(apiProxy) {
        console.log('AplayerPlayHistory initApiProxy');
        this.apiProxy = apiProxy;
        this.apiProxy.AttachServerEvent('AplayerPlayHistoryPrepared', ()=>{
            this.eventContainor.emit('AplayerPlayHistoryPrepared');
        });
        this.apiProxy.AttachServerEvent('AplayerPlayHistoryItemUpdate', (item, newAdd)=>{
            this.eventContainor.emit('AplayerPlayHistoryItemUpdate', item, newAdd);
            if (newAdd) {
                this.listCache.unshift(item);
            } else {
                const replaceIndex = this.listCache.findIndex((i)=>i.id === item.id);
                if (replaceIndex > -1) {
                    this.listCache.splice(replaceIndex, 1, item);
                }
            }
        });
        this.apiProxy.AttachServerEvent('AplayerPlayHistoryItemDelete', (id)=>{
            this.eventContainor.emit('AplayerPlayHistoryItemDelete', id);
            const delIndex = this.listCache.findIndex((i)=>i.id === id);
            if (delIndex > -1) {
                this.listCache.splice(delIndex, 1);
            }
        });
    }
    async search(key) {
        if (this.listCache.length === 0) {
            this.listCache = await this.getList();
        }
        let items = [];
        this.listCache.forEach((item)=>{
            if (item.name.toLowerCase().includes(key.toLowerCase())) {
                items.push(item);
            }
        });
        return items;
    }
    async deleteItem(id) {
        await this.apiProxy.CallApi('AplayerPlayHistoryDeleteItem', id);
    }
    async deleteAllItem(isClearServer, p0) {
        console.log('AplayerPlayHistory deleteAllItem', isClearServer);
        const info = await this.apiProxy.CallApi('AplayerPlayHistoryDeleteAllItem', isClearServer);
        console.log('AplayerPlayHistory deleteAllItem info', info);
        if (info.bSucc) {
            return info.result;
        }
        return false;
    }
    async getItemById() {
        let info = await this.apiProxy.CallApi('AplayerPlayHistoryGetItemById');
        if (info.bSucc) {
            return info.result;
        }
        return {};
    }
    async playItem(id, stats) {
        await this.apiProxy.CallApi('AplayerPlayHistoryPlayItem', id, stats);
    }
    async getList() {
        this.listCache = await this.getListImpl();
        return this.listCache;
    }
    async getListImpl() {
        let info = await this.apiProxy.CallApi('AplayerPlayHistoryGetList');
        if (info.bSucc) {
            return info.result;
        }
        return [];
    }
    async asyncLoadAll() {
        let info = await this.apiProxy.CallApi('AplayerPlayHistoryAsyncLoadAll');
        if (info.bSucc) {
            return info.result;
        }
        return [];
    }
    async getSelect() {
        let info = await this.apiProxy.CallApi('AplayerPlayHistoryGetSelect');
        if (info.bSucc) {
            return info.result;
        }
        return false;
    }
    async isPrepared() {
        let info = await this.apiProxy.CallApi('AplayerPlayHistoryIsPrepared');
        if (info.bSucc) {
            return info.result;
        }
        return false;
    }
    attachPreparedEvent(cb) {
        this.eventContainor.on('AplayerPlayHistoryPrepared', cb);
    }
    detachPreparedEvent(cb) {
        this.eventContainor.off('AplayerPlayHistoryPrepared', cb);
    }
    attachItemUpdate(cb) {
        this.eventContainor.on('AplayerPlayHistoryItemUpdate', cb);
    }
    detachItemUpdate(cb) {
        this.eventContainor.off('AplayerPlayHistoryItemUpdate', cb);
    }
    attachItemDeleteEvent(cb) {
        this.eventContainor.on('AplayerPlayHistoryItemDelete', cb);
    }
    detachItemDeleteEvent(cb) {
        this.eventContainor.off('AplayerPlayHistoryItemDelete', cb);
    }
}

