//import { server } from '@xunlei/node-net-ipc/dist/ipc-server';
class PlayerCallApiProxy {
    clientName = common_env/* PlayerIPCClientName */.W3;
    async CallApi(name, ...args) {
        try {
            let result = await ipc_client.client.callRemoteClientFunction(this.clientName, name, ...args);
            return {
                bSucc: true,
                result: result[0]
            };
        } catch (e) {
            return {
                bSucc: false
            };
        }
    }
    AttachServerEvent(name, callback) {
        return ipc_client.client.attachServerEvent(name, (c, ...args)=>{
            callback(...args);
        });
    }
    DetachServerEvent(name, cookie) {
        ipc_client.client.detachServerEvent(name, cookie);
    }
    async DestoryObject(id) {
        ipc_client.client.callServerFunction('DestoryObject', id);
    }
}

