class WaitSomeThing {
    bDone = false;
    cbs = [];
    async waitDone() {
        if (!this.bDone) {
            await new Promise((v)=>{
                this.cbs.push(()=>{
                    v(true);
                });
            });
        }
    }
    done() {
        this.bDone = true;
        let temp = this.cbs;
        this.cbs = [];
        temp.forEach((cb)=>{
            cb();
        });
    }
    isDone() {
        return this.bDone;
    }
    reset() {
        this.bDone = false;
    }
}

