/**
   * 可扩展的多位版本号比对函数
   * @param {string} currentVersion 当前版本号 (如 "3.2.8.1")
   * @param {string} serverVersion 服务器版本号 (如 "3.2.9.0")
   * @returns {Object} 包含比对结果的对象
   *   {
   *     shouldUpdate: boolean,  // 是否需要更新
   *     isCurrentHigher: boolean, // 当前版本是否更高
   *     differenceIndex: number,  // 第一个不同版本段的位置
   *     differenceType: string,   // 差异类型 'major'|'minor'|'patch'|'build'|'custom'
   *     currentParts: number[],   // 当前版本分解后的数字数组
   *     serverParts: number[]     // 服务器版本分解后的数字数组
   *   }
   */ function compareFlexibleVersions(currentVersion, serverVersion) {
    // 参数校验
    if (typeof currentVersion !== 'string' || typeof serverVersion !== 'string') {
        throw new Error('版本号必须是字符串');
    }
    // 分割版本号为数字数组
    const currentParts = currentVersion.split('.').map((part)=>{
        const num = parseInt(part, 10);
        if (isNaN(num)) throw new Error(`无效的版本号部分: ${part}`);
        return num;
    });
    const serverParts = serverVersion.split('.').map((part)=>{
        const num = parseInt(part, 10);
        if (isNaN(num)) throw new Error(`无效的版本号部分: ${part}`);
        return num;
    });
    // 确定最大长度
    const maxLength = Math.max(currentParts.length, serverParts.length);
    // 预定义的版本段类型（可扩展）
    const versionSegmentTypes = [
        'major',
        'minor',
        'patch',
        'build'
    ];
    for(let i = 0; i < maxLength; i++){
        // 如果某一部分不存在则视为0
        const currentPart = currentParts[i] || 0;
        const serverPart = serverParts[i] || 0;
        if (serverPart > currentPart) {
            return {
                shouldUpdate: true,
                isCurrentHigher: false,
                differenceIndex: i,
                differenceType: versionSegmentTypes[i] || `custom-${i}`,
                currentParts,
                serverParts
            };
        } else if (serverPart < currentPart) {
            return {
                shouldUpdate: false,
                isCurrentHigher: true,
                differenceIndex: i,
                differenceType: versionSegmentTypes[i] || `custom-${i}`,
                currentParts,
                serverParts
            };
        }
    }
    // 所有部分都相同
    return {
        shouldUpdate: false,
        isCurrentHigher: false,
        differenceIndex: -1,
        differenceType: 'none',
        currentParts,
        serverParts
    };
}
