async function registerBossKeyOnce(bossKeyHotkeyReset) {
    let isSuccess = false;
    try {
        await waitMainWindowInited.waitDone();
        // 第一步反注册上次老板键
        if (preBossKeyHotkey) {
            console.log('bossKey unregister', (0,common_hotkeys/* transformHotkeyToShortcut */.RB)(preBossKeyHotkey));
            external_electron_.globalShortcut.unregister((0,common_hotkeys/* transformHotkeyToShortcut */.RB)(preBossKeyHotkey));
        }
        const settingData = await (0,settingConfigStore.getSettingStoreData)();
        const hotkey = bossKeyHotkeyReset ? bossKeyHotkeyReset : settingData.hotkeys.boss;
        let bossKeyShortcut = (0,common_hotkeys/* transformHotkeyToShortcut */.RB)(hotkey);
        if (bossKeyShortcut) {
            console.log('bossKey register', bossKeyShortcut);
            external_electron_.globalShortcut.register(bossKeyShortcut, ()=>{
                handleBossKey();
            });
        }
        isSuccess = true;
        preBossKeyHotkey = hotkey;
    } catch (error) {
        isSuccess = false;
    }
    console.log('bossKey register isSuccess=', isSuccess);
    if (isSuccess) {
        return {
            isSuccess: true,
            bossKeyHotkeyReset: bossKeyHotkeyReset ?? null
        };
    }
    if (!bossKeyHotkeyReset && preBossKeyHotkey) {
        // 注册新老板键失败, 重置老板键
        return await registerBossKeyOnce(preBossKeyHotkey);
    }
    // 注册新老板键(没有可重置)失败, 重置老板键失败
    return {
        isSuccess: false,
        bossKeyHotkeyReset: bossKeyHotkeyReset ?? null
    };
}
/** 串行执行，避免配置监听与设置页 invoke 并发注册 */ let registerBossKeyChain = Promise.resolve();
function scheduleRegisterBossKey(bossKeyHotkeyReset) {
    const next = registerBossKeyChain.then(()=>registerBossKeyOnce(bossKeyHotkeyReset));
    registerBossKeyChain = next.then(()=>undefined, ()=>undefined);
    return next;
}
